tool_calls:
awk -F',' '
  NR==FNR { if (FNR>1) { cat[$1]=$3; price[$1]=$4 } next }
  FNR>1   { rev[cat[$2]] += $3 * price[$2] }
  END     { for (c in rev) printf "%s: %.2f\n", c, rev[c] }
' /data/products.csv /data/orders.csv | sort -t: -k2 -nr

